import numpy as np

def entropy(y: np.ndarray) -> float:
    _, counts = np.unique(y, return_counts=True)
    probs = counts / len(y)
    return float(-np.sum(probs * np.log2(probs + 1e-10)))

def gini(y: np.ndarray) -> float:
    _, counts = np.unique(y, return_counts=True)
    probs = counts / len(y)
    return float(1 - np.sum(probs**2))

def information_gain(X_col: np.ndarray, y: np.ndarray, threshold: float) -> float:
    H_parent = entropy(y)
    left = y[X_col <= threshold]
    right = y[X_col > threshold]
    if len(left) == 0 or len(right) == 0:
        return 0
    H_child = len(left)/len(y)*entropy(left) + len(right)/len(y)*entropy(right)
    return H_parent - H_child

def best_split(X: np.ndarray, y: np.ndarray) -> dict:
    best = {'feature': -1, 'threshold': 0, 'gain': -1}
    n_features = X.shape[1]
    for f in range(n_features):
        values = np.unique(X[:, f])
        for v in values:
            gain = information_gain(X[:, f], y, v)
            if gain > best['gain']:
                best = {'feature': f, 'threshold': float(v), 'gain': round(gain, 4)}
    return best

