def _build_stump(X, y, depth=0, max_depth=3):
    if len(set(y)) == 1 or depth >= max_depth:
        return {'pred': Counter(y).most_common(1)[0][0], 'leaf': True}
    best_gain, best_f, best_t = -1, -1, 0
    for f in range(X.shape[1]):
        for v in np.unique(X[:, f]):
            left = y[X[:, f] <= v]
            right = y[X[:, f] > v]
            if len(left) == 0 or len(right) == 0:
                continue
            H = lambda y: -sum((c/len(y))*np.log2(c/len(y)+1e-10) for c in Counter(y).values())
            gain = H(y) - len(left)/len(y)*H(left) - len(right)/len(y)*H(right)
            if gain > best_gain:
                best_gain, best_f, best_t = gain, f, v
    if best_f == -1:
        return {'pred': Counter(y).most_common(1)[0][0], 'leaf': True}
    left_idx = X[:, best_f] <= best_t
    return {'feature': best_f, 'threshold': best_t, 'leaf': False,
            'left': _build_stump(X[left_idx], y[left_idx], depth+1, max_depth),
            'right': _build_stump(X[~left_idx], y[~left_idx], depth+1, max_depth)}

def fit_random_forest(X, y, n_trees=5, max_depth=3):
    trees = []
    for _ in range(n_trees):
        Xs, ys = bootstrap_sample(X, y)
        trees.append(_build_stump(Xs, ys, 0, max_depth))
    return trees

def _predict_tree(tree, x):
    if tree.get('leaf'):
        return tree['pred']
    if x[tree['feature']] <= tree['threshold']:
        return _predict_tree(tree['left'], x)
    return _predict_tree(tree['right'], x)

