    mse_right = np.var(right) * len(right)
    return (mse_left + mse_right) / len(y)
def best_split(X, y):
    best_f, best_t, best_loss = -1, 0, float("inf")
    for f in range(X.shape[1]):
        vals = np.unique(X[:, f])
